80	export function tick(input, ctx) {
81	  const st = input.state ?? { o: null };
82	  const me = input.instance;
83	  let subject = st.o?.id ?? null;
84	
85	  // --- a new instance started by an inbound message (§3.2): merge it into its order's case, or start one
86	  const openFor = oid => rowsOf(ctx.instances({ subject: oid })).map(x => (typeof x === 'string' ? x : x?.instance))
87	    .filter(x => x && x !== me);
88	
89	  // --- the order record: st.o = { id, customerId, currency, p, ed, email, reviewHours, actionHours, fs, coll, phase, cleared, ended }
90	  const o = () => st.o;
91	
92	  function startOrder(ev) {
93	    const p = ev.payload;
94	    const oid = norm(p.orderId);
95	    const ed = editionAt(ctx, p.placedAt);
96	    const r = rulesOf(ctx, ed);
97	    const cust = mapOf(jsonOf(ctx.files['master/customers.json']), ['customerId', 'id'], ['email']);
98	    const cat = mapOf(jsonOf(ctx.files['master/catalog.json']), ['sku'], ['unitPriceMinor']);
99	    const prices = {};
100	    for (const it of p.items ?? []) if (cat[it.sku] !== undefined) prices[it.sku] = cat[it.sku];
