102	      reviewHours: r.policy.fraudReviewHours, actionHours: r.policy.customerActionHours, fs: {}, coll: {}, phase: 'allocating',
103	      cleared: false, ended: null };
104	    ctx.call('intake', oid, { op: 'place', orderId: oid, customerId: p.customerId, placedAt: p.placedAt, currency: p.currency,
