109	  // R2.2: a review task opens (its deadline is fixed from this first task)
110	  function openReview(at) {
111	    const x = o();
112	    if (x.ended || x.cleared || x.phase === 'review') return;
113	    x.phase = 'review';
114	    ctx.call('review', x.id, { op: 'open', orderId: x.id, reviewHours: x.reviewHours, at });
115	  }
116	
117	  // R3.1 or R4.1: the order is cleared at t; with unavailable items the customer is asked first
118	  function clearAt() {
119	    const x = o();
120	    if (x.ended || x.cleared) return;
121	    x.cleared = true;
122	    if (Object.values(x.fs).some(f => !f.avail)) {
123	      x.phase = 'waiting';
124	      ctx.call('wait', x.id, { op: 'arm', orderId: x.id, p: x.p, customerActionHours: x.actionHours, email: x.email,
125	        fulfilments: Object.entries(x.fs).map(([fulfilmentId, f]) => ({ fulfilmentId, available: f.avail })) });
