231	      }
232	      return;
233	    }
234	    if (p.action === 'amend' && x.phase === 'waiting') {
235	      const w = ctx.call('wait', x.id, { op: 'action', at: ev.at, action: 'amend' });
236	      if (w?.counted !== 'amend') return;
237	      for (const f of Object.values(x.fs)) if (!f.avail) f.status = 'cancelled';
238	      if (w.nothingAvailable) return cancelOrder('nothing-available', ev.at);   // R3.2
239	      startProcessing();                                                       // ready at a (R4)
240	    }
241	  }
242	
243	  // §3.3 carrier messages (R4.4): routed to the fulfilment by its fulfilmentRef
