// go-live (§3.5): a fulfilment already in flight continues from what its records show. A reserved item, a charge or a
// booked shipment in the records is a step that committed; the first step not shown is issued with its own key, which
// the system answers with the original result if it had already committed (§1).
function adoptFulfilment(input, st) {
  if (st) return { output: { phase: st.phase } };
  const items = input.items.map((it, i) => ({ key: `r${i}`, sku: it.sku, qty: it.qty }));
  const left = [...(input.reservedSkus ?? [])];
  const res = {};
  for (const it of items) {
    const j = left.indexOf(it.sku);
    if (j >= 0) { left.splice(j, 1); res[it.key] = 'ok'; }
  }
  const next = { orderId: input.orderId, fid: input.fid, location: input.location, customerId: input.customerId, email: input.email,
    currency: input.currency, amountMinor: input.amountMinor, items, res, charge: 'none', ship: 'none', carrier: null,
    phase: 'reserving', undone: {}, attempts: 0, bad: {} };
  if (input.dispatched) {                                   // collected already: every step committed (R4.4)
    for (const it of items) res[it.key] = 'ok';
    return { state: { ...next, charge: 'ok', ship: 'ok', phase: 'dispatched' }, output: { phase: 'dispatched' } };
  }
  if (items.some(it => res[it.key] !== 'ok')) return { state: next, effects: [reserveEffect(next)], output: { phase: 'reserving' } };
  next.charge = input.charged ? 'ok' : 'none';
  next.ship = input.shipped ? 'ok' : 'none';
  if (next.charge !== 'ok') return { state: { ...next, phase: 'charging' }, effects: [chargeEffect(next)], output: { phase: 'charging' } };
  if (next.ship !== 'ok') return { state: { ...next, phase: 'shipping' }, effects: [shipEffect(next)], output: { phase: 'shipping' } };
  return { state: { ...next, phase: 'shipped' }, output: { phase: 'shipped' } };
}

export function step(input, ctx) { return fitAll(stepRaw(input, ctx), ctx.files); }

