// §3.5 go-live: a migrated order continues from its records, waiting for the customer (R3) or processing (R4) with
// each fulfilment where it stands. Statuses and notices already recorded are not sent again.
function adopt(row, records, at) {
  const oid = norm(row.orderId);
  const ed = editionAt(ctx, row.placedAt);
  const r = rulesOf(ctx, ed);
  const cust = mapOf(jsonOf(ctx.files['master/customers.json']), ['customerId', 'id'], ['email']);
  const x = { id: oid, customerId: row.customerId, currency: row.currency, p: row.placedAt, ed, email: cust[row.customerId] ?? '',
    reviewHours: r.policy.fraudReviewHours, actionHours: r.policy.customerActionHours, fs: {}, coll: {}, phase: 'checking',
    cleared: true, ended: null };
  for (const f of rowsIn(records, 'orders.fulfilments')) {
    if (norm(f.orderId) !== oid) continue;
    x.fs[f.fulfilmentId] = { loc: f.location ?? null, amt: f.amountMinor, items: f.items ?? [], avail: f.location != null, status: f.status };
  }
  st.o = x;
  subject = oid;
  if (['completed', 'failed', 'cancelled', 'timedOut'].includes(row.status)) { x.ended = row.status; x.phase = 'ended'; return; }
  if (row.status === 'customerActionRequired') {
    x.phase = 'waiting';
    ctx.call('wait', oid, { op: 'adopt', orderId: oid, p: x.p, customerActionHours: x.actionHours, email: x.email,
      fulfilments: Object.entries(x.fs).map(([fulfilmentId, f]) => ({ fulfilmentId, available: f.avail })) });
    return;
  }
  if (row.status === 'processing') {
    x.phase = 'processing';
    for (const [fid, f] of Object.entries(x.fs)) {
      if (!f.avail) continue;
      if (f.status === 'pending') startFulfilment(x, fid, f);
      else if (f.status === 'dispatched') {
        x.coll[fid] = at;                                   // collected before go-live: the customer can no longer cancel (S7)
        ctx.call('fulfil', `${oid}.${fid}`, { op: 'adopt', ...fulfilArgs(x, fid, f), dispatched: true });
      } else if (f.status === 'processing') {
        ctx.call('fulfil', `${oid}.${fid}`, { op: 'adopt', ...fulfilArgs(x, fid, f), dispatched: false, ...factsOf(records, fid) });
      }
    }
    maybeOutcome();
  }
}

